/* Material_Motion_Surface_Spec V1.1, S7 historical tokens; project Web adapter. */
(()=>{'use strict';
const media=matchMedia('(prefers-reduced-motion: reduce)'),jobs=new Set();
const reduced=()=>media.matches||document.body.classList.contains('reduced');
class Spring{constructor(value,draw,z=.8,k=380){this.x=value;this.v=0;this.target=value;this.draw=draw;this.z=z;this.k=k;this.frame=0;this.last=0;this.done=null}to(target,done){this.target=target;this.done=done;if(reduced()||document.hidden){this.finish();return}jobs.add(this);if(!this.frame){this.last=performance.now();this.frame=requestAnimationFrame(t=>this.tick(t))}}tick(t){let dt=Math.min((t-this.last)/1000,.25);this.last=t;while(dt>0){const h=Math.min(dt,1/240);this.v+=(-this.k*(this.x-this.target)-2*this.z*Math.sqrt(this.k)*this.v)*h;this.x+=this.v*h;dt-=h}this.draw(this.x);if(Math.abs(this.x-this.target)<.15&&Math.abs(this.v)<.15){this.finish();return}this.frame=requestAnimationFrame(t=>this.tick(t))}finish(){cancelAnimationFrame(this.frame);this.frame=0;this.x=this.target;this.v=0;this.draw(this.x);jobs.delete(this);const f=this.done;this.done=null;f?.()}cancel(){cancelAnimationFrame(this.frame);this.frame=0;this.done=null;jobs.delete(this)}}
const fade=(el)=>{if(!el||reduced()||document.hidden)return;el.getAnimations().forEach(a=>a.cancel());el.animate([{opacity:0},{opacity:1}],{duration:160,easing:'linear'})};
const states=new WeakMap();
document.addEventListener('click',e=>{const summary=e.target.closest('#today-summary>summary');if(!summary)return;e.preventDefault();const d=summary.parentElement,body=d.querySelector('.summary-body');let state=states.get(d);if(!state){state={open:d.open,spring:new Spring(d.getBoundingClientRect().height,v=>{d.style.height=Math.max(0,v)+'px'})};states.set(d,state)}if(!jobs.has(state.spring)){state.open=d.open;state.spring.x=d.getBoundingClientRect().height}state.open=!state.open;const closed=summary.getBoundingClientRect().height;d.open=true;d.style.overflow='hidden';body.inert=!state.open;body.setAttribute('aria-hidden',String(!state.open));summary.setAttribute('aria-expanded',String(state.open));const expanded=closed+body.getBoundingClientRect().height;state.spring.to(state.open?expanded:closed,()=>{d.open=state.open;d.style.height='';d.style.overflow='';if(state.open)body.inert=false});},true);
const presses=new WeakMap();document.addEventListener('pointerdown',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;let s=presses.get(b);if(!s){s=new Spring(0,v=>b.style.translate=`0 ${v}px`,.6,800);presses.set(b,s)}s.to(1.5);b.dataset.pressed='true'});function release(){document.querySelectorAll('[data-pressed]').forEach(b=>{delete b.dataset.pressed;presses.get(b)?.to(0)})}document.addEventListener('pointerup',release);document.addEventListener('pointercancel',release);window.addEventListener('blur',release);
const panel=document.querySelector('#panel');let panelSpring;new MutationObserver(()=>{if(panel.classList.contains('onboarding')){panelSpring?.cancel();panel.style.translate='';return}if(!panel.open){panelSpring?.cancel();panel.style.translate='';return}if(panelSpring&&jobs.has(panelSpring))return;panelSpring?.cancel();panelSpring=new Spring(panel.classList.contains('drawer')?-36:48,v=>panel.style.translate=panel.classList.contains('drawer')?`${v}px 0`:`0 ${v}px`,.8,200);panelSpring.to(0,()=>panel.style.translate='');fade(panel)}).observe(panel,{attributes:true,attributeFilter:['open']});
panel.querySelector('.panel-head').addEventListener('pointerdown',()=>{panelSpring?.cancel();panel.style.translate=''});
new MutationObserver(()=>{fade(document.querySelector('#native-page'));const title=document.querySelector('#native-title');if(!title.hidden){title.tabIndex=-1;title.focus({preventScroll:true})}}).observe(document.querySelector('#app'),{attributes:true,attributeFilter:['data-route']});
function settle(){if(reduced()||document.hidden){[...jobs].forEach(s=>s.finish());document.getAnimations().forEach(a=>{if(a.effect?.getComputedTiming().iterations===Infinity)a.cancel();else a.finish()})}}media.addEventListener('change',settle);new MutationObserver(settle).observe(document.body,{attributes:true,attributeFilter:['class']});document.addEventListener('visibilitychange',settle);
// Animate only new messages; persistence and rendering never wait for motion.
const seen=new WeakSet();const messages=document.querySelector('#messages');
function reveal(el){if(!el||reduced()||document.hidden)return;const spring=new Spring(14,v=>{if(el.isConnected)el.style.translate=`0 ${v}px`;else spring.cancel()},.8,380);spring.to(0,()=>el.style.translate='');fade(el)}
new MutationObserver(()=>{messages.querySelectorAll('[data-arriving]').forEach(el=>{el.removeAttribute('data-arriving');reveal(el)})}).observe(messages,{subtree:true,attributes:true,attributeFilter:['data-arriving']});
new MutationObserver(()=>{const form=document.querySelector('#onboard-form');if(form&&!seen.has(form)){seen.add(form);reveal(form.querySelector('.ob-character-row'));reveal(form.querySelector('.ob-step-content'))}}).observe(document.querySelector('#panel-body'),{childList:true});
document.addEventListener('visibilitychange',()=>document.body.classList.toggle('motion-paused',document.hidden));
window.MaterialMotion={Spring,reduced,collapseSummary(){const d=document.querySelector('#today-summary');if(!d)return;const state=states.get(d);state?.spring.cancel();if(state)state.open=false;d.open=false;d.style.height='';d.style.overflow='';const body=d.querySelector('.summary-body');if(body){body.inert=true;body.setAttribute('aria-hidden','true')}d.querySelector('summary').setAttribute('aria-expanded','false')}};
})();
